function sens(s){      // どの前提が 1 段動くと、探知距離（1 回の Pd）が何 % 動くか
  const b = calc(s).r1, d = o => (calc(Object.assign({}, s, o)).r1 / b - 1) * 100, i = NS.indexOf(s.npdi);
  return [['平均電力 +1 dB', d({pavdb: s.pavdb + 1})], ['損失 +1 dB', d({ladj: s.ladj + 1})], ['P_FA を 1/10 に', d({x: s.x + 1})], ['P_d を +0.05', s.pd <= 0.94 ? d({pd: s.pd + 0.05}) : NaN], ['N_pdi を 2 倍に', i < NS.length - 1 ? d({npdi: NS[i + 1]}) : NaN], [s.sw === 0 ? 'Swerling 1 に' : 'ゆらがないに', d({sw: s.sw === 0 ? 1 : 0})]];
}
